ת חושי", "targets": ["t1"], "sentences": ["בוקר טוב, זה אני", "לאט לאט", "יש לנו זמן"], "avoid": "לא להדליק אור חזק בבת אחת"}, {"id": "i2", "name": "לתלות לוח בוקר", "what": "לוח תמונות עם שלבי הבוקר בגובה העיניים, ומסמנים כל שלב.", "why": "לוח חזותי מחליף תזכורות ומונע ויכוח.", "freq": "כל בוקר", "approach": "ARC", "targets": ["t2"], "sentences": ["מה בתמונה הבאה?", "סימנת!", "עוד שלב אחד"]}, {"id": "i3", "name": "להפוך למשחק", "what": "שלבי הבוקר עם משחק קטן: צחצוח עם שיר, הלבשה מהירה של בובה.", "why": "משחק מוריד התנגדות בבוקר.", "freq": "כל בוקר", "approach": "ARC", "targets": ["t3"], "sentences": ["נצחצח עד שהשיר נגמר", "מי לובש קודם, אתה/את או הדובי?", "צחצחת עד הסוף"]}, {"id": "i4", "name": "להכין בערב", "what": "בערב בוחרים יחד את הבגדים למחר ושמים אותם במקום.", "why": "בחירה בערב מקצרת את הבוקר.", "freq": "כל ערב", "approach": "ARC", "targets": ["t4", "t5"], "sentences": ["מה נלבש מחר?", "נשים פה, מוכן לבוקר", "מחר רק לובשים"]}, {"id": "i5", "name": "להציע בחירה קטנה", "what": "בבוקר נותנים בחירה בין שתיים (כוס, דגני בוקר), ולא שאלה פתוחה.", "why": "בחירה קטנה נותנת שליטה בלי להאט.", "freq": "כל בוקר", "approach": "TBRI", "targets": ["t4"], "sentences": ["כחולה או צהובה?", "בחרת", "יופי"]}, {"id": "i6", "name": "לשמור על אותו סדר", "what": "אותו סדר שלבים כל בוקר, גם בסופי שבוע ככל שאפשר.", "why": "סדר קבוע מרגיע את הגוף.", "freq": "כל יום", "approach": "NMT", "targets": ["t2", "t1"], "sentences": ["כמו כל בוקר", "עכשיו, כמו תמיד, הדבר הבא", "אתה/את כבר יודע/ת"]}, {"id": "i7", "name": "לתת זמן מספיק", "what": "מתחילים מוקדם מספיק כדי לא למהר, כדי שלא נצטרך למהר.", "why": "לחץ זמן מביא סערות.", "freq": "כל בוקר", "approach": "ARC", "targets": ["t5"], "sentences": ["יש לנו זמן", "לא ממהרים", "סיימנו בזמן"]}, {"id": "i8", "name": "לסיים בברכה", "what": "ביציאה, ברכה קבועה ומשפט על מה שיקרה בצהריים.", "why": "פרידה צפויה מקלה על היציאה.", "freq": "כל בוקר", "approach": "TBRI", "targets": ["t5"], "sentences": ["יום טוב, מחכים לך כאן אחרי הגן", "נשמח לשמוע איך הי