insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'לוח היום בכרטיסים', 'לדעת מה יש היום ולנהל את הסדר בעצמי, בעזרת כרטיסים', array['מעברים ושגרה']::text[], 'מעברים ושגרה', array['CPS', 'ARC', 'NMT', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להעמיס יותר מדי כרטיסים, ולא להשתמש בלוח לעונשים", "strengths": ["עצמאות", "אחריות", "סדר"], "skills": ["ארגון"], "main": "6-9", "also": ["2-5"], "evidence": {"level": "derived", "note": "תמיכות חזותיות ולוחות זמנים נמצאו מועילים לילדים עם קשיי קשב, אוטיזם וטראומה. במסגרות חוץ־ביתיות זו התאמה יישומית שלא נבדקה ישירות."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "בבוקר, מסתכל/ת על לוח היום ואומר/ת מה יש היום", "staff": "בודק/ת בלוח מה יש היום", "scale": ["עדיין לא מתעניין/ת", "מסתכל/ת כשמראים", "אומר/ת מה יש כשמבוגר שואל", "בודק/ת לבד", "מכין/ה את עצמו/ה לפי הלוח"]}, {"id": "t2", "text": "מסמן/ת או מזיז/ה כרטיס כשמשימה נגמרת", "staff": "מזיז/ה כרטיס כשמסיים/ת", "scale": ["עדיין לא", "מזיז/ה עם מבוגר", "מזיז/ה עם תזכורת", "מזיז/ה לבד", "מזיז/ה ובודק/ת מה הבא"]}, {"id": "t3", "text": "כשיש שינוי בלוח, מקבל/ת אותו אחרי הסבר", "staff": "מסכים/ה כשמשהו בלוח משתנה", "scale": ["עדיין מתפרץ/ת בכל שינוי", "נרגע/ת עם מבוגר", "מתלונן/ת ומקבל/ת", "מקבל/ת עם הסבר", "שואל/ת על שינויים מראש"]}, {"id": "t4", "text": "עובר/ת בין משימות לפי הלוח עם מעט תזכורות", "staff": "עובר/ת בין משימות לפי הלוח", "scale": ["עדיין רק עם תזכורת צמודה", "עם הרבה תזכורות", "עם תזכורת אחת", "לבד ברוב הזמן", "לבד ומזכיר/ה לחבר"]}, {"id": "t5", "text": "עוזר/ת לבנות את הלוח לשבוע", "staff": "עוזר/ת לבנות את הלוח", "scale": ["עדיין לא משתתף/ת", "מסתכל/ת", "בוחר/ת כרטיס אחד", "בונה חלק", "מציע/ה מה להוסיף"]}], "interventions": [{"id": "i1", "name": "לבנות יחד לוח יומי", "what": "בונים יחד לוח עם כרטיסים של היום, במקום שרואים.", "why": "לוח שבניתי מובן לי יותר.", "freq": "בתחילת השבוע, ומתעדכן", "approach": "CPS", "targets": ["t5", "t1"], "sentences": ["מה יש לנו היום?", "איזה כרטיס בא אחרי?", "איפה נתלה?"]}, {"id": "i2", "name": "לעבור על הלוח בבוקר", "what": "בבוקר עוברים יחד דקה על הלוח, ומציינים דבר אחד טוב שמחכה.", "why": "הצצה בבוקר מכינה את הראש ליום.", "freq": "כל בוקר", "approach": "ARC", "targets": ["t1"], "sentences": ["מה יש היום?", "מה הכי מחכה לך?", "יאללה, מתחילים"]}, {"id": "i3", "name": "להזיז כרטיס בסיום", "what": "כשמשימה נגמרת, מזיזים את הכרטיס ל''סיימתי''.", "why": "הזזה מסמנת התקדמות ומראה מה נשאר.", "freq": "בכל סיום", "approach": "ARC", "targets": ["t2", "t4"], "sentences": ["סיימת, תזיז/י", "מה הבא בלוח?", "תראה/תראי כמה עשית"]}, {"id": "i4", "name": "לתרגל שינוי קטן במשחק", "what": "במשחק מחליפים בכוונה כרטיס בלוח, ומתרגלים יחד מה עושים כשמשהו משתנה.", "why": "שינוי שתורגל במשחק מפחיד פחות במציאות.", "freq": "בכל שינוי", "approach": "NMT", "targets": ["t3"], "sentences": ["עכשיו נחליף כרטיס בכוונה", "מה עושים עכשיו?", "התמודדת עם שינוי"]}, {"id": "i5", "name": "להפנות ללוח במקום להזכיר", "what": "במקום לומר מה לעשות, שואלים: מה אומר הלוח?", "why": "הלוח לוקח את מקום התזכורת, והילד לומד לנהל.", "freq": "בכל מעבר", "approach": "ARC", "targets": ["t4"], "sentences": ["מה אומר הלוח?", "אתה/את יודע/ת מה הבא", "ניהלת את זה לבד"]}, {"id": "i6", "name": "לשמור על מעט כרטיסים", "what": "על הלוח רק החלקים העיקריים של היום, לא כל פרט.", "why": "לוח עמוס מבלבל.", "freq": "תמיד", "approach": "NMT", "targets": ["t1", "t4"], "sentences": ["רק הדברים הגדולים", "את השאר נזכור יחד", "פשוט וברור"]}, {"id": "i7", "name": "לשבח שימוש בלוח", "what": "משבחים כשבדק/ה בלוח לבד.", "why": "מה שמשבחים חוזר.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t1", "t4"], "sentences": ["בדקת לבד בלוח", "ניהלת את היום", "יפה מאוד"]}, {"id": "i8", "name": "להעביר את הלוח לבית הספר", "what": "בתיאום עם המטפלת, כרטיסים דומים או לוח כיס גם בבית הספר.", "why": "אותה שפה בשני המקומות מקלה על הילד.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t4"], "sentences": ["גם בבית הספר יש לך לוח", "אותם כרטיסים", "איך זה ע