"name": "לשמוח על הצלחה בבית הספר", "what": "כשמשהו הצליח בבית הספר, חוגגים בקטן ומספרים לצוות.", "why": "הצלחה שרואים כאן מחזקת את בית הספר.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t3"], "sentences": ["סיפרת שהצלחת במבחן!", "אני גאה בך", "נספר לכולם?"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'להתכונן לשינוי בלוח הזמנים', 'להתמודד עם שינויים בתוכנית בלי להתפרק', array['מעברים ושגרה']::text[], 'מעברים ושגרה', array['ARC', 'CPS', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להסתיר שינוי ידוע, ולא לומר ''זה לא משנה''", "strengths": ["גמישות", "אומץ", "שליטה עצמית"], "skills": ["גמישות"], "main": "10-12", "also": ["13-15"], "evidence": {"level": "derived", "note": "נגזר מעקרונות הטיפול מותאם הטראומה (צפיות ושליטה), מ-CPS ומ-ARC. אצל ילדים אחרי טראומה שינויים פתאומיים מעוררים איום; ההתערבויות הן התאמה יישומית."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "כשמודיעים על שינוי מראש, שואל/ת שאלות במקום להתפרץ", "staff": "שואל/ת על שינוי במקום להתפרץ", "scale": ["עדיין מתפרץ/ת", "מתפרץ/ת ונרגע/ת עם מבוגר", "מתלונן/ת ומקבל/ת", "שואל/ת שאלות", "שואל/ת ומתכנן/ת"]}, {"id": "t2", "text": "כשהשינוי פתאומי, משתמש/ת בדרך הרגעה שלו/ה", "staff": "נרגע/ת בעצמו/ה כשמשהו משתנה פתאום", "scale": ["עדיין מתפרק/ת", "נרגע/ת עם מבוגר לאט", "נרגע/ת עם מבוגר מהר", "משתמש/ת בדרך הרגעה לבד", "נרגע/ת מהר ומחפש/ת פתרון"]}, {"id": "t3", "text": "מציע/ה תוכנית ב'' כשמשהו מתבטל", "staff": "מציע/ה מה לעשות במקום", "scale": ["עדיין לא מציע/ה", "מסכים/ה לתוכנית של מבוגר", "בוחר/ת מתוך שתיים", "מציע/ה בעצמו/ה", "מציע/ה ועוזר/ת לאחרים"]}, {"id": "t4", "text": "בודק/ת בלוח או שואל/ת על שינויים צפויים לשבוע", "staff": "בודק/ת מה ישתנה השבוע", "scale": ["עדיין לא מתעניין/ת", "מקשיב/ה כשמספרים", "שואל/ת לפעמים", "בודק/ת בעצמו/ה", "מתכנן/ת את השבוע לפי השינויים"]}, {"id": "t5", "text": "מדבר/ת על מה מרגיש/ה כשדברים משתנים", "staff": "מספר/ת מה מרגיש/ה כשמשהו משתנה", "scale": ["עדיין לא מדבר/ת", "מראה בהתנהגות", "אומר/ת מילה אחת", "מספר/ת ברוגע", "מקשר/ת לחוויות קודמות (בהנחיית המטפלת)"]}], "interventions": [{"id": "i1", "name": "להודיע מוקדם ככל האפשר", "what": "על כל שינוי ידוע מודיעים מוקדם, עם מה, מתי ולמה, במילים פשוטות.", "why": "שינוי שיודעים עליו מראש מאיים פחות.", "freq": "בכל שינוי ידוע", "approach": "ARC", "targets": ["t1", "t4"], "sentences": ["רציתי לספר לך מראש", "ביום חמישי יהיה שינוי", "מה עוד תרצה/תרצי לדעת?"]}, {"id": "i2", "name": "לעבור על השבוע", "what": "פעם בשבוע עוברים יחד על השבוע ומסמנים שינויים צפויים.", "why": "תמונת שבוע מגדילה תחושת שליטה.", "freq": "באופן קבוע", "approach": "CPS", "targets": ["t4"], "sentences": ["מה יש השבוע?", "מה שונה מהרגיל?", "איך מתכוננים?"]}, {"id": "i3", "name": "לתרגל תוכנית ב''", "what": "במצבים רגועים מתרגלים: אם זה מתבטל, מה נעשה במקום?", "why": "מי שתרגל תוכנית ב'' לא נתקע כשמשהו מתבטל.", "freq": "מדי פעם", "approach": "CPS", "targets": ["t3"], "sentences": ["ואם זה מתבטל?", "מה עוד אפשר?", "יש לך תוכנית ב''"]}, {"id": "i4", "name": "להזכיר את דרך ההרגעה", "what": "כשהשינוי פתאומי, מזכירים בשקט את הכלי שעובד לו/ה (נשימה, פינה, מוזיקה).", "why": "כלי מוכר זמין גם ברגע של הפתעה.", "freq": "בכל שינוי פתאומי", "approach": "ARC", "targets": ["t2"], "sentences": ["זה מפתיע, אני יודע/ת", "מה עוזר לך עכשיו?", "אני כאן"]}, {"id": "i5", "name": "לתת שם לרגש", "what": "אחרי שנרגע/ת, מדברים על מה הרגיש/ה כשהדבר השתנה.", "why": "מילים לרגש עוזרות לווסת אותו בפעם הבאה.", "freq": "אחרי שינוי קשה", "approach": "ARC", "targets": ["t5"], "sentences": ["מה הרגשת כשזה השתנה?", "זה מובן", "מה עזר לך?"], "avoid": "לא לחפור בחוויות עבר בלי המטפלת"}, {"id": "i6", "name": "לתת בחירה גם בתוך השינוי", "what": "גם כשיש שינוי, נותנים בחירה בתוכו: מתי, עם מי, באיזה סדר.", "why": "בחירה קטנה מחזירה תחושת שליטה.", "freq": "בכל שינוי", "approach": "CPS", "targets": ["t3", "t1"], "sentences": ["את זה לא אנחנו מחליטים", "אבל את זה אתה/את בוחר/ת", "מה תעדיף/תעדיפי?"]}, {"id": "i7", "name": "לומר את האמת", "what": "כשלא יודעים, אומרים שלא יודעים ומתי נדע.", "why": "אמת שמתאימה לגיל בונה אמון.", "freq": "תמיד", "approach": "ARC", "targets": ["t1"], "sentences": ["עוד לא יודעים", "אני אספר לך כשאדע", "זה מתסכל לחכות"], "avoid": "לא להבטיח מה שלא בטוח"}, {"id": "i8", "name": "ל